import logging

import time

from selenium.webdriver import ActionChains
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.by import By
from selenium.webdriver.support.wait import WebDriverWait

from taf.selenium.gnb.oam.coam.vdu.common.exceptions import ParamValueError
from taf.selenium.gnb.oam.coam.vdu.pages.LoginPage import LoginPage


class Menu(LoginPage):
    """
    The class manages which menu tab will be clicked
    """
    DEFAULT_MENU_LENGTH = 3
    FIRST_MENU_INDEX = 0
    SECOND_MENU_INDEX = 1
    LAST_MENU_INDEX = -1

    def perform_element_hover_by_xpath(self, xpath):
        try:
            element = WebDriverWait(self._driver, 10).until(
                EC.presence_of_element_located((By.XPATH, xpath))
            )
            WebDriverWait(self._driver, 10).until(
                EC.visibility_of(element)
            )
            ActionChains(self._driver).move_to_element(element).pause(0.2).perform()
        except Exception as e:
            logging.info(f"Hover failed for {xpath}: {e}")

    @property
    def is_firefox(self):
        return 'firefox' in self._driver.capabilities.get('browserName', '').lower()

    def open_page(self, menu_list):  # noqa: C901
        if not menu_list:
            raise ParamValueError("menu list is empty")

        menu_xpath_list = [self.locator.MAIN_MENU_XPATH.format(menu_list[self.FIRST_MENU_INDEX]),
                           self.locator.SIDEBAR_XPATH,
                           self.locator.SUB_MENU_XPATH.format(menu_list[self.SECOND_MENU_INDEX])]

        if len(menu_list) == self.DEFAULT_MENU_LENGTH:
            menu_xpath_list.append(self.locator.TARGET_TAB_XPATH.format(menu_list[self.LAST_MENU_INDEX]))

        if self._is_page_active(menu_list):
            return

        for index, xpath in enumerate(menu_xpath_list):
            self.perform_element_hover_by_xpath(xpath)
            time.sleep(0.3)

            if index == len(menu_xpath_list) - 1:
                if self.is_firefox:
                    self._driver.set_window_size(1920, 1280)
                    self._hover_and_click_firefox(menu_xpath_list)
                else:
                    self.click_enabled_element(xpath, 60)

        time.sleep(2)

    def _hover_and_click_firefox(self, menu_xpath_list):
        """
        This method is a workaround for Firefox to handle hover and click actions.
        It first moves the mouse outside the menu to reset any open submenus,
        then hovers over each menu item in the provided list, and finally clicks
        the last item in the list using JavaScript for reliability.

        :param list menu_xpath_list: List of XPaths for the menu items to hover and click.
        :raises Exception: If any error occurs during the hover and click process.

        """
        try:
            body = WebDriverWait(self._driver, 10).until(
                EC.presence_of_element_located((By.TAG_NAME, "body"))
            )
            ActionChains(self._driver).move_to_element_with_offset(body, 0, 0).perform()
            time.sleep(0.7)
            from selenium.webdriver.common.keys import Keys
            body.send_keys(Keys.ESCAPE)
            time.sleep(0.5)

            for xpath in menu_xpath_list[:-1]:
                elem = WebDriverWait(self._driver, 15).until(
                    EC.visibility_of_element_located((By.XPATH, xpath))
                )
                ActionChains(self._driver).move_to_element(elem).pause(1.0).perform()
                time.sleep(1.0)

            final_xpath = menu_xpath_list[-1]

            final_elem = WebDriverWait(self._driver, 20).until(
                EC.visibility_of_element_located((By.XPATH, final_xpath))
            )

            MAX_CLICK_RETRIES = 3
            for attempt in range(1, MAX_CLICK_RETRIES + 1):
                try:
                    WebDriverWait(self._driver, 5).until(
                        EC.element_to_be_clickable((By.XPATH, final_xpath))
                    )
                    self._driver.execute_script("arguments[0].click();", final_elem)
                    time.sleep(1)
                    break
                except Exception as click_exception:
                    logging.info(f"[Click attempt {attempt}] failed: {click_exception}")
                    time.sleep(0.7)
                    if attempt == MAX_CLICK_RETRIES:
                        raise

        except Exception as e:
            logging.info(f"[Firefox workaround] Exception during hover and click: {e}")
            raise

    def _is_page_active(self, menu_list):
        if self.element_exists((By.XPATH, self.locator.ACTIVE_TAB_XPATH), timeout=1):
            return menu_list[self.LAST_MENU_INDEX] == self.get_text(self.locator.ACTIVE_TAB_XPATH)
        else:
            return menu_list[self.LAST_MENU_INDEX] == self.get_text(self.locator.ACTIVE_TITLE_XPATH)
